def excluded_share(self, arm):
    cells = [c for (a, _), trials in self.cells.items() if a == arm for c in trials.values()]
    if not cells:
        return None, 0, 0
    ex = sum(1 for c in cells if c["valid"] is None)
    return ex / len(cells), ex, len(cells)

